-- HOLIDAYS · Halloween · Halloween · 13+ · continuing
do $mig$
declare
  v_course uuid; v_unit uuid; v_lesson uuid;
  v_media text := 'https://classroom.wowteach.ru/media/';
begin
  select id into v_course from classroom_courses where slug = 'holidays';
  if v_course is null then raise exception 'course holidays not found'; end if;

  select id into v_unit from classroom_units
   where course_id = v_course and title = 'Halloween' limit 1;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order)
    values (v_course, 'Halloween', 1) returning id into v_unit;
  end if;

  select id into v_lesson from classroom_lessons
   where unit_id = v_unit and title = 'Halloween · 13+ · continuing' limit 1;
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, summary, sort_order, is_published, pass_threshold, kind)
    values (v_unit, 'Halloween · 13+ · continuing', 'Урок-игра для 13+ лет, продолжающие', 6, false, 60, 'lesson')
    returning id into v_lesson;
  else
    update classroom_lessons set summary = 'Урок-игра для 13+ лет, продолжающие', sort_order = 6,
           is_published = false, pass_threshold = 60, kind = 'lesson'
     where id = v_lesson;
  end if;

  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
    -- блок 1 (sort_order 0) · интерактивный урок
    (v_lesson, 'embed', replace($blk${"url": "https://classroom.wowteach.ru/lessons/halloween/13plus_continuing.html"}$blk$, '@@MEDIA@@', v_media)::jsonb, 0),
    -- блок 2 (sort_order 1) · как провести — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<div style=\"padding:16px 18px;background:#fff7ec;border-radius:14px;border:2px solid #f3d3a3\">\n<h3 style=\"margin:0 0 6px;color:#8a3c08\">🎃 Как провести урок</h3>\n<p style=\"margin:0 0 8px\">«Планы уроков» → этот урок → <b>«▶ Показ»</b>: урок откроется на весь экран. Демонстрируйте в Zoom <b>эту вкладку</b>, а не весь экран.</p>\n<p style=\"margin:0 0 8px\">План урока — кнопка 📋 вверху справа внутри урока (откроется отдельным окном) или ниже на этой странице.</p>\n<p style=\"margin:0\">Если удобнее отдельной вкладкой: <a href=\"https://classroom.wowteach.ru/lessons/halloween/13plus_continuing.html\">открыть урок</a>. Нужен интернет: картинки и музыка загружаются с сервера.</p></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 1),
    -- блок 3 (sort_order 2) · план — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>План урока</h3><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Длительность:</b> 40 мин. &nbsp; <b>Мотивация:</b> escape room — ученик собирает ключ от особняка, попадает внутрь, дверь захлопывается; в каждой из 5 комнат он узнаёт кусок истории Хэллоуина и получает цифру кода. Код каждый урок новый.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>📖 История для учителя:</b> Хэллоуин начался больше 2000 лет назад с кельтского праздника <b>Samhain</b> — конец урожая и начало зимы; верили, что граница между миром живых и мёртвых в эту ночь тонкая, жгли костры и наряжались, чтобы духи не узнали. Позже Церковь сделала 1 ноября Днём всех святых (All Hallows' Day), вечер накануне — <b>All Hallows' Eve → Halloween</b>. Легенда о <b>Скупом Джеке</b> объясняет фонарь jack-o'-lantern: в Ирландии и Шотландии их резали из <b>репы</b>, в Америке — из тыквы. Дети ходили по домам в масках, пели и читали стихи за угощение (<b>guising</b>) — отсюда trick-or-treat. В 1840-х ирландские переселенцы привезли праздник в Америку; слова «trick or treat» впервые напечатаны в Канаде (Альберта) в 1927 г. Сегодня американцы тратят на Хэллоуин около 13,1 млрд $ (прогноз NRF на 2025 г.). Факты сверены с источниками (Tourism Ireland, Smithsonian, Guinness, NRF).</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🗣 Произношение.</b> Перед уроком убедитесь, что правильно произносите эти слова (британская транскрипция):<table style=\"border-collapse:collapse;margin:8px 0\"><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Samhain</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈsaʊɪn/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Halloween</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˌhæləʊˈiːn/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>All Hallows' Eve</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˌɔːl ˈhæləʊz ˈiːv/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>All Saints' Day</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˌɔːl ˈseɪnts deɪ/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Celts</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/kelts/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Celtic</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈkeltɪk/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>harvest</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈhɑːvɪst/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>costume</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈkɒstjuːm/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>guising</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈɡaɪzɪŋ/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>mansion</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈmænʃn/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>spirits</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈspɪrɪts/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>haunted</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈhɔːntɪd/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>vampire</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈvæmpaɪə/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>pirate</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈpaɪrət/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>myth</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/mɪθ/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>centuries</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈsentʃəriz/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>recognise</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈrekəɡnaɪz/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Guinness</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈɡɪnɪs/</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>carve</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/kɑːv/</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>carving</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\">/ˈkɑːvɪŋ/</td></tr></table></div><div style=\"background:#fff3cd;border:3px solid #c0392b;border-radius:12px;padding:12px 16px;margin:10px 0;font-weight:700;color:#7a1f12\">⚠️ ЕСЛИ НЕ ХВАТАЕТ ВРЕМЕНИ — НАЖМИТЕ ЗНАЧОК 🗝 (CODE ROOM, ВВЕРХУ СПРАВА, РЯДОМ С 📋). ОН ЕСТЬ НА ВСЕХ СТРАНИЦАХ ДО ДВЕРИ. ЗА КАЖДУЮ НЕДОСТАЮЩУЮ ЦИФРУ УЧЕНИК ОТВЕЧАЕТ НА ОДИН БЫСТРЫЙ ВОПРОС (ВЫБОР ИЗ ТРЁХ), ПОТОМ — СРАЗУ К ДВЕРИ. СТРЕЛКА ← ВЕРНЁТ ТУДА, ОТКУДА ВЫ ПРИШЛИ.</div><table style=\"width:100%;border-collapse:collapse;font-size:14px\"><tr><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Стр.</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Задание и инструкция</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Teacher's language</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Suggested answers / Students' answers</th></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">1</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Lead-in.</b> Улица в ночь Хэллоуина. Вопрос <b>What's the topic?</b> — ученик угадывает, Next открывает ответ «Halloween». Дальше учитель <b>сам задаёт 1–2 вопроса</b> (на экране их нет).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's the topic?\" \"What symbols of Halloween do you know?\" \"Do people celebrate Halloween in your country?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Halloween!\" \"Pumpkins, ghosts, bats, witches…\" \"Not really, but some young people have parties.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">2</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Слова (8).</b> Сначала картинка: ученик пробует назвать, нажатие показывает слово и <b>произносит</b>. Next открывает следующую.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's this?\" \"Repeat!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A lantern. The harvest…\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">3</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Zoom in (6 раундов).</b> Картинка сильно увеличена и медленно отдаляется. Ученик называет слово как можно раньше; нажатие на картинку / Next — слово появляется на экране (без озвучки: произносит ученик). В конце — <b>половинка ключа</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What is it? Guess!\" \"Quick!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Is it a candle?\" \"It's a bonfire!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">4</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Missing letters (6 слов).</b> Картинка и слово, в котором пропущены 3–4 буквы. Ученик называет буквы, учитель нажимает их на клавиатуре. Слева медленно проявляется и растёт <b>призрак</b> (18 сек.), каждая неверная буква его приближает. Успели — призрак исчезает; не успели — «BOO!», недостающие буквы появляются красным. Next — подсказка. В конце — <b>вторая половинка ключа</b>.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Which letters are missing? Spell the word.\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"B-O-N-F-I-R-E.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">5</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Особняк.</b> Две половинки ключа (за Zoom in и Missing letters) уже соединились в панели KEY. Нажмите на дверь (или Next) — ключ летит в замок, дверь со скрипом открывается.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What can you see? Would you go inside?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It looks scary but I'd go in.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">6</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Холл: фонарик.</b> Темно. Учитель водит фонарик мышкой (без мыши он бродит сам), ученик говорит, куда светить, и называет найденные предметы — учитель нажимает. Нашли всё — зажигается свет, на экране распахнутая входная дверь… и она <b>захлопывается</b>. Записка: «The door is locked. To escape, find the 5-digit code. Each room hides one digit.» Дальше 5 комнат = 5 цифр.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Where shall I shine the torch? Left or right?\" \"What's that?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Go up… stop! It's an old lantern.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">7</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Библиотека: Samhain.</b> Текст, где выученные слова заменены картинками: ученик читает вслух и вместо картинки называет слово (нажатие на картинку показывает слово). Потом — <b>True / False</b> (6); текст остаётся на экране, ученик ищет ответ в нём. Past Simple, passive (were lit), used to. За задание — <b>цифра кода</b> (появляется в панели CODE слева).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Read the text, please.\" \"Is it true or false?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"False — bonfires were lit at the end of the harvest, not to celebrate the summer.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">8</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Кухня: комикс «Samhain night».</b> Ирландия, давным-давно: Нора и её брат Лиам готовятся к Самайну — фонарь из репы, костёр, призрак, маски. 6 кадров, в каждом два облачка. Ученик вписывает все 12 реплик (сначала фразы к кадрам 1–3, потом к 4–6): выбирает фразу справа и нажимает на облачко. Потом <b>пересказывает историю</b>: First… Then… In the end… Неверно — кадр трясётся. В конце — карточка о фонарях из репы. За задание — <b>цифра кода</b> (появляется в панели CODE слева).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who says this? Why do they wear masks? Retell the story.\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"First, Nora carved a turnip… In the end the ghost ran away from the lantern.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">9</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Бальный зал: откуда традиции.</b> Соедините традицию и её происхождение (нажать слева, потом справа). Потом обсуждение: «What would you dress up as and why?» — 6 костюмов для опоры. За задание — <b>цифра кода</b> (появляется в панели CODE слева).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Where does trick-or-treating come from?\" \"What would you dress up as? Why?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I'd dress up as a pirate because…\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">10</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Подвал: Myth or fact? (6).</b> Утверждение с картинкой, кнопки MYTH / FACT. После верного ответа — короткое объяснение. Среди фактов — самая тяжёлая тыква в мире: 1 247 кг (рекорд Гиннесса, 2023). За задание — <b>цифра кода</b> (появляется в панели CODE слева).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Myth or fact? Why do you think so?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a myth — the first lanterns were turnips.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">11</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Чердак: Halloween goes to America.</b> 6 карточек без дат. Ученик говорит, что было раньше, учитель нажимает на карточку — она встаёт в первую свободную ячейку (нажатие на карточку в ячейке возвращает её). Когда все разложены — <b>✓ Check</b>: на всех карточках появляются даты, верные остаются на месте (зелёные), неверные возвращаются вниз — ученик раскладывает их заново, уже по датам. За задание — <b>цифра кода</b> (появляется в панели CODE слева).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What happened first? And then? Now look at the dates.\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"In the 1840s Irish families moved to America and brought Halloween with them.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">12</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Дверь.</b> Ученик называет код по цифрам из панели CODE, учитель вводит его на замке. Неверно — замок трясётся. Next вводит код сам.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's the code?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Seven, two, nine, four, one!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">13</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Escaped!</b> Дверь открывается на праздник. Окно «What's your name?» → <b>сертификат</b> «This is to certify that [имя] escaped from Samhain Mansion on Halloween night», 💾 Save — скачать картинкой. Внизу <b>🏁 Finish</b> (финальный слайд) и <b>⭐ Extra</b> (доп. задания).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Congratulations! You escaped!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Yay!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">14</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Extra 1: Halloween bucket list.</b> Нажатие на карточку — в список, в списке — убрать, внизу свой пункт.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Imagine your perfect Halloween night. What would you do?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I'd like to visit a haunted house because…\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">15</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Extra 2: настольная игра.</b> Фишки (1–5 игроков, можно вписать имена) → ▶ Play. Кубик по очереди. На клетках «?» — вопросы о Хэллоуине, отвечать развёрнуто. ⏩ +2, ⏪ −2, ⭐ весёлые задания. Первый у дверей особняка — победил.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Answer the question. Why?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I don't believe in ghosts because…\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">16</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Finish.</b> «Well done! Happy Halloween!»</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Happy Halloween! Bye!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Happy Halloween!\"</td></tr></table><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🗂️ Лексика и грамматика:</b> pumpkin, turnip, bonfire, costume, ghost, candle, lantern, harvest • Past Simple, Past Continuous, used to, passive (were lit, was shortened) • I'd dress up as… because… • myth / fact</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0;font-size:13px;color:#777\"><b>Навигация:</b> ← → — назад / пропустить; Next ведёт к следующему раунду (подсказывает ответ), когда задание выполнено — к следующей странице. Кружочки вверху слева кликабельны. 🗝 — Code room, 📋 — этот план, 🎵 — музыка.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🏠 Домашнее задание</b> — материал <b>«Halloween Homework · 13+ · continuing»</b> на платформе: «Материалы» → «Задать ДЗ» → ученик → отметить. Только слова урока, 10–15 минут. Задания:<ol style=\"margin:6px 0 0 22px\"><li>Карточки с переводом</li><li>Соедини слово и определение</li><li>Собери слово из букв</li><li>Послушай и напиши</li><li>Текст о Самайне с пропусками</li><li>True / False по тексту</li><li>🎤 Расскажи, как ты празднуешь Хэллоуин</li></ol><div style=\"color:#777;font-size:13px;margin-top:4px\">Устные задания ученик записывает голосом — их вы слушаете и оцениваете в «Проверке ДЗ».</div></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 2),
    -- блок 4 (sort_order 3) · ДЗ — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Halloween Homework · 13+ · continuing»</b> в этом же юните. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 3)
  on conflict (lesson_id, sort_order) do update
    set type = excluded.type, payload = excluded.payload;

  delete from classroom_blocks where lesson_id = v_lesson and sort_order >= 4;
  update classroom_blocks set audience = 'shared' where lesson_id = v_lesson and sort_order = 0;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 1;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 2;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 3;
end
$mig$;
